<?php declare(strict_types=1);use FastWebsite\Core\View;$x=static fn(string$f):string=>(string)($values[$f]??'');$dt=static fn(string$v):string=>$v!==''?str_replace(' ','T',substr($v,0,16)):'';$edit=is_int($itemId);?>
<section class="admin-page-heading"><div><p class="eyebrow">Calendar</p><h1><?=$edit?'Edit event':'Create event'?></h1><p>Published events remain editable.</p></div><a class="button button-secondary" href="<?=View::escape($baseUrl)?>admin/events">Cancel</a></section><?php if($errors!==[]):?><div class="form-alert"><ul><?php foreach($errors as$e):?><li><?=View::escape($e)?></li><?php endforeach;?></ul></div><?php endif;?><form class="content-form" enctype="multipart/form-data" method="post" action="<?=View::escape($baseUrl)?>admin/events<?=$edit?'/'.$itemId:''?>"><input type="hidden" name="_token" value="<?=View::escape($csrfToken)?>"><section class="form-section"><div class="form-grid"><div class="form-field span-2"><label>Title *</label><input name="title" required maxlength="300" value="<?=View::escape($x('title'))?>"></div><div class="form-field"><label>Category *</label><select name="category_id"><?php foreach($categories as$c):?><option value="<?=(int)$c['id']?>"<?=$x('category_id')===(string)$c['id']?' selected':''?>><?=View::escape($c['name'])?></option><?php endforeach;?></select></div><div class="form-field"><label>Lead department</label><select name="department_id"><option value="">Faculty-wide</option><?php foreach($departments as$d):?><option value="<?=(int)$d['id']?>"<?=$x('department_id')===(string)$d['id']?' selected':''?>><?=View::escape($d['name'])?></option><?php endforeach;?></select></div><div class="form-field"><label>Starts *</label><input type="datetime-local" name="starts_at" required value="<?=View::escape($dt($x('starts_at')))?>"></div><div class="form-field"><label>Ends</label><input type="datetime-local" name="ends_at" value="<?=View::escape($dt($x('ends_at')))?>"></div><div class="form-field"><label>Public URL</label><input name="slug" value="<?=View::escape($x('slug'))?>"></div><div class="form-field"><label>Event status</label><select name="event_status"><?php foreach(['scheduled','postponed','cancelled','completed']as$s):?><option<?=$x('event_status')===$s?' selected':''?>><?=$s?></option><?php endforeach;?></select></div><div class="form-field span-2"><label>Summary</label><textarea name="summary" rows="3"><?=View::escape($x('summary'))?></textarea></div><div class="form-field span-2"><label>Description</label><textarea name="description" rows="9"><?=View::escape($x('description'))?></textarea></div><div class="form-field"><label>Venue</label><input name="venue_name" value="<?=View::escape($x('venue_name'))?>"></div><div class="form-field"><label>Saved location</label><select name="location_id"><option value="">None</option><?php foreach($locations as$l):?><option value="<?=(int)$l['id']?>"<?=$x('location_id')===(string)$l['id']?' selected':''?>><?=View::escape(trim(implode(', ',array_filter([$l['campus'],$l['building'],$l['room']]))))?></option><?php endforeach;?></select></div><div class="form-field"><label>Contact staff</label><select name="contact_staff_id"><option value="">None</option><?php foreach($staff as$s):?><option value="<?=(int)$s['id']?>"<?=$x('contact_staff_id')===(string)$s['id']?' selected':''?>><?=View::escape(trim(implode(' ',array_filter([$s['honorific_title'],$s['first_name'],$s['middle_name'],$s['last_name']]))))?></option><?php endforeach;?></select></div><div class="form-field"><label>Contact name</label><input name="contact_name" value="<?=View::escape($x('contact_name'))?>"></div><div class="form-field"><label>Contact email</label><input type="email" name="contact_email" value="<?=View::escape($x('contact_email'))?>"></div><div class="form-field"><label>Registration URL</label><input type="url" name="registration_url" value="<?=View::escape($x('registration_url'))?>"></div><div class="form-field"><label>Registration deadline</label><input type="datetime-local" name="registration_deadline" value="<?=View::escape($dt($x('registration_deadline')))?>"></div></div></section><section class="form-section"><h2>Image</h2><div class="form-grid"><div class="form-field"><label>Reuse image</label><select name="featured_media_id"><option value="">No image</option><?php foreach($images as$i):?><option value="<?=(int)$i['id']?>"<?=$x('featured_media_id')===(string)$i['id']?' selected':''?>><?=View::escape($i['original_name'])?></option><?php endforeach;?></select></div><div class="form-field"><label>Upload image</label><input type="file" name="featured_image" accept="image/*"></div><div class="form-field"><label>Image description</label><input name="image_alt_text"></div></div></section><div class="form-actions"><button class="button button-secondary" name="submit_action" value="save">Save</button><button class="button button-primary" name="submit_action" value="publish">Save and publish</button></div></form>
